def _unfilled_size(chunk: int, fixed_chunk: int) -> int:
    """Return how much is needed to complete ``chunk`` to a grid boundary."""
    return (fixed_chunk - chunk % fixed_chunk) % fixed_chunk


def _validate_backend_chunks(
    v_chunks: tuple[int, ...], backend_chunks: tuple[int, ...]
) -> int:
    if sum(v_chunks) != sum(backend_chunks):
        raise ValueError(
            "The total number of elements in backend chunks must match the "
            "total number of elements in variable chunks."
        )

    if not backend_chunks:
        raise ValueError("backend chunks cannot be empty")

    fixed_chunk = max(backend_chunks)
    if fixed_chunk <= 0 or any(chunk <= 0 for chunk in backend_chunks):
        raise ValueError("chunk sizes must be positive integers")

    # Backend chunks are expected to form a regular grid.  The first and last
    # chunks may be partial because a write region can start or stop in the
    # middle of a backend chunk, but all interior chunks must have the fixed
    # grid size.
    for chunk in backend_chunks[1:-1]:
        if chunk != fixed_chunk:
            raise ValueError(
                "Backend chunks are not uniformly sized. This is an internal "
                "error that should be reported."
            )

    if len(backend_chunks) > 1:
        if backend_chunks[0] > fixed_chunk or backend_chunks[-1] > fixed_chunk:
            raise ValueError(
                "Backend chunks are not uniformly sized. This is an internal "
                "error that should be reported."
            )

    return fixed_chunk


def _split_aligned_chunks(
    chunks: list[int], fixed_chunk: int, max_chunk: int
) -> list[int]:
    """Merge/split chunks so internal boundaries lie on the fixed grid."""
    aligned: list[int] = []

    def ensure_last_can_be_filled() -> None:
        """Split an unfilled oversized chunk into aligned prefix and tail."""
        while aligned:
            last = aligned[-1]
            unfilled = _unfilled_size(last, fixed_chunk)
            if unfilled == 0 or last + unfilled <= max_chunk:
                break

            remainder = last % fixed_chunk
            if remainder == 0:
                break
            prefix = last - remainder
            if prefix <= 0:
                break
            aligned[-1] = prefix
            aligned.append(remainder)

    for chunk in chunks:
        remaining = chunk
        while remaining > 0:
            if not aligned or _unfilled_size(aligned[-1], fixed_chunk) == 0:
                if remaining > max_chunk:
                    # Starting from a grid boundary, choose the largest grid-
                    # aligned chunk that respects max_chunk.
                    size = max_chunk - (max_chunk % fixed_chunk)
                    if size <= 0:
                        size = max_chunk
                    aligned.append(size)
                    remaining -= size
                else:
                    aligned.append(remaining)
                    remaining = 0
                    ensure_last_can_be_filled()
                continue

            unfilled = _unfilled_size(aligned[-1], fixed_chunk)
            ideal_size = aligned[-1] + remaining
            if ideal_size <= max_chunk:
                aligned[-1] = ideal_size
                remaining = 0
                ensure_last_can_be_filled()
            else:
                # Increase the last chunk by as much as possible without
                # exceeding max_chunk, while preserving grid alignment.  This
                # follows the formula in the interface description.
                room = max_chunk - aligned[-1]
                max_increase = room - ((room - unfilled) % fixed_chunk)
                if max_increase <= 0:
                    ensure_last_can_be_filled()
                    # If the split above did not make progress, fall back to
                    # the minimal fill needed to reach the next grid boundary.
                    if max_increase <= 0:
                        max_increase = min(remaining, unfilled)

                increase = min(remaining, max_increase)
                aligned[-1] += increase
                remaining -= increase
                ensure_last_can_be_filled()

    return aligned


def _remove_prefix(chunks: list[int], amount: int) -> list[int]:
    chunks = list(chunks)
    while amount and chunks:
        if chunks[0] > amount:
            chunks[0] -= amount
            amount = 0
        else:
            amount -= chunks.pop(0)
    return chunks


def _remove_suffix(chunks: list[int], amount: int) -> list[int]:
    chunks = list(chunks)
    while amount and chunks:
        if chunks[-1] > amount:
            chunks[-1] -= amount
            amount = 0
        else:
            amount -= chunks.pop()
    return chunks


def _merge_modified_border(
    chunks: list[int], original_border_chunk: int, max_chunk: int
) -> list[int]:
    if (
        len(chunks) >= 2
        and chunks[0] != original_border_chunk
        and chunks[0] + chunks[1] <= max_chunk
    ):
        return [chunks[0] + chunks[1], *chunks[2:]]
    return chunks


def _align_1d_chunks(
    v_chunks: tuple[int, ...], backend_chunks: tuple[int, ...]
) -> tuple[int, ...]:
    fixed_chunk = _validate_backend_chunks(v_chunks, backend_chunks)

    if len(v_chunks) == 1:
        return v_chunks

    # If there is only one backend chunk, all variable chunks would otherwise
    # overlap that same storage chunk; collapse them into a single chunk.
    if len(backend_chunks) == 1:
        return (sum(v_chunks),)

    max_chunk = max(fixed_chunk, *v_chunks)

    first_padding = fixed_chunk - backend_chunks[0]
    last_padding = fixed_chunk - backend_chunks[-1]

    padded_chunks = list(v_chunks)
    padded_chunks[0] += first_padding
    padded_chunks[-1] += last_padding

    aligned = _split_aligned_chunks(padded_chunks, fixed_chunk, max_chunk)

    aligned = _remove_prefix(aligned, first_padding)
    aligned = _remove_suffix(aligned, last_padding)

    # Avoid inefficient tiny border chunks introduced solely by the artificial
    # padding.  Apply the optimization at the front and then at the back by
    # reversing the chunks, as described in the interface documentation.
    aligned = _merge_modified_border(aligned, v_chunks[0], max_chunk)
    aligned = list(reversed(_merge_modified_border(list(reversed(aligned)), v_chunks[-1], max_chunk)))

    if sum(aligned) != sum(v_chunks):
        raise ValueError("aligned chunks do not preserve the original size")

    return tuple(aligned)


def align_nd_chunks(
    nd_v_chunks: tuple[tuple[int, ...], ...],
    nd_backend_chunks: tuple[tuple[int, ...], ...],
) -> tuple[tuple[int, ...], ...]:
    """
    Align n-dimensional variable chunks to backend storage chunks.

    Backend chunks must form a uniform grid in each dimension, except that the
    first and last chunks may be partial border chunks.  The returned chunks
    preserve the shape of the input while ensuring chunk boundaries are aligned
    to backend chunk boundaries where possible and do not exceed
    ``max(fixed_backend_chunk, *variable_chunks)`` in each dimension.
    """
    if len(nd_v_chunks) != len(nd_backend_chunks):
        raise ValueError(
            "The number of dimensions in backend chunks must match variable chunks."
        )

    return tuple(
        _align_1d_chunks(v_chunks, backend_chunks)
        for v_chunks, backend_chunks in zip(nd_v_chunks, nd_backend_chunks, strict=True)
    )


def build_grid_chunks(
    size: int, chunk_size: int, region: slice | None = None
) -> tuple[int, ...]:
    """Build backend-grid chunk sizes for a one-dimensional write region."""
    if chunk_size <= 0:
        raise ValueError("chunk_size must be a positive integer")
    if size < 0:
        raise ValueError("size must be non-negative")
    if size == 0:
        return ()

    if region is None:
        region = slice(0, size)

    start = region.start or 0
    if start < 0:
        raise ValueError("region.start must be non-negative")

    first_chunk = chunk_size - (start % chunk_size)
    if first_chunk >= size:
        return (size,)

    chunks = [first_chunk]
    remaining = size - first_chunk
    chunks.extend([chunk_size] * (remaining // chunk_size))
    remainder = remaining % chunk_size
    if remainder:
        chunks.append(remainder)

    return tuple(chunks)


def grid_rechunk(
    v: Variable, enc_chunks: tuple[int, ...], region: tuple[slice, ...]
) -> Variable:
    """Rechunk a chunked Variable so its chunks align to a backend grid."""
    if not is_chunked_array(v._data):
        return v

    if len(enc_chunks) != v.ndim:
        raise ValueError(
            "The number of encoding chunks must match the number of variable dimensions."
        )
    if len(region) != v.ndim:
        raise ValueError(
            "The number of region slices must match the number of variable dimensions."
        )

    nd_backend_chunks = tuple(
        build_grid_chunks(size=size, chunk_size=chunk_size, region=dim_region)
        for size, chunk_size, dim_region in zip(
            v.shape, enc_chunks, region, strict=True
        )
    )
    aligned_chunks = align_nd_chunks(v.chunks, nd_backend_chunks)

    if aligned_chunks == v.chunks:
        return v

    return v.chunk(dict(zip(v.dims, aligned_chunks, strict=True)))
